using Microsoft.Extensions.Configuration;using Serilog;
namespace QLNhaTro;
internal static class Program{[STAThread]static void Main(){ApplicationConfiguration.Initialize();Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Log.Logger=new LoggerConfiguration().WriteTo.File("Logs/app-.log",rollingInterval:RollingInterval.Day).CreateLogger();Application.ThreadException+=(_,e)=>{Log.Error(e.Exception,"UI exception");MessageBox.Show("Đã xảy ra lỗi, thông tin đã được ghi lại");};AppDomain.CurrentDomain.UnhandledException+=(_,e)=>Log.Fatal(e.ExceptionObject as Exception,"Unhandled exception");var c=new ConfigurationBuilder().SetBasePath(AppContext.BaseDirectory).AddJsonFile("appsettings.json",false,true).Build();Application.Run(new MainForm(c.GetConnectionString("QL_NhaTro")!));}}
